import {Guardian} from './core/guardian.js';
import {SIGNAL_LABELS,ACTIONS} from './core/signal_extractor.js';
import {STAGES} from './core/scam_graph.js';
import {POLICY_LABELS} from './core/intervention_policy.js';
import {SCENARIOS} from './scenarios.js';
const $=selector=>document.querySelector(selector);
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const engine=new Guardian();
let scenario='refund',step=0,timer=null,currentView='dashboard',familyEvent=null,toastTimer=null,analysisEpoch=0;
const time=seconds=>`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;
const last=()=>engine.history.at(-1);
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function showView(view){if(!['dashboard','senior','family','about'].includes(view))return;currentView=view;document.body.dataset.view=view;document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==view);document.querySelectorAll('.nav').forEach(el=>{el.classList.toggle('active',el.dataset.view===view);el.setAttribute('aria-current',el.dataset.view===view?'page':'false');});}
function stop(){if(timer)clearInterval(timer);timer=null;$('#play').textContent=step>=SCENARIOS[scenario].turns.length?'↻ 再演示一次':'▶ 播放演示';}
function reset(){analysisEpoch++;stop();window.speechSynthesis?.cancel();engine.reset();step=0;familyEvent=null;$('#custom-text').value='';$('#input-status').textContent=$('#model-mode')?.checked?'在线模型模式：输入将发送最近最多8句到您配置的服务。':'输入仅在本页内存中处理。重置或刷新后清除。';render();$('#play').textContent='▶ 播放演示';}
function next(){const data=SCENARIOS[scenario].turns[step];if(!data){stop();return;}step++;ingest(data[1],{seconds:Math.max(data[0],(last()?.seconds??-1)+1),source:'script'});if(step>=SCENARIOS[scenario].turns.length)stop();}
function togglePlay(){if(timer){stop();return;}if(step>=SCENARIOS[scenario].turns.length)reset();next();if(step<SCENARIOS[scenario].turns.length){timer=setInterval(next,12000);$('#play').textContent='Ⅱ 暂停演示';}}
function speak(event){if(!$('#voice').checked||!event.policy.speak)return;if(!('speechSynthesis'in window)){toast('当前浏览器不支持语音，请查看屏幕上的提醒。');return;}window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(`${event.policy.title}。请先暂停操作，和家人确认。`);utterance.lang='zh-CN';utterance.rate=.85;utterance.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))toast('语音暂不可用，请查看屏幕上的安全提醒。');};window.speechSynthesis.speak(utterance);}
function ingest(text,options={}){analysisEpoch++;const event=engine.process(text,options);render();speak(event);return event;}
function policyTheme(){return(engine.policy?.level??0)>=3?'danger':(engine.policy?.level??0)>=1?'caution':'';}
function seniorCopy(){const p=engine.policy;if(!p)return {title:'有我陪着，<br>慢慢说。',description:'点击开始，体验一次安心陪护。'};if(p.reportedHarm)return {title:'先停止<br>后续操作。',description:'您说已经操作过。请尽快联系家人，并通过官方渠道求助。'};if(p.level>=3)return {title:'先别操作。',description:escape(p.title)+'。<br>请先暂停，找家人确认。'};if(p.level>=1)return {title:'咱们先<br>慢一点。',description:escape(p.title)+'。'};return {title:'我在听，<br>您慢慢说。',description:'暂未发现需要主动打断的动作。'};}
function renderChart(){const events=engine.history.slice(-12);const points=[{risk:0},...events.map(e=>({risk:e.risk.risk}))];const coords=points.map((p,i)=>[35+i*650/Math.max(5,points.length-1),85-p.risk*72]);const path=coords.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)} ${y.toFixed(1)}`).join(' ');const fill=path+` L${coords.at(-1)[0]} 85 L35 85Z`;
 $('#risk-chart').innerHTML=`<svg viewBox="0 0 710 112" preserveAspectRatio="none" role="img" aria-label="最近${events.length}句风险分：${events.map(e=>Math.round(e.risk.risk*100)).join('、')||'尚无对话'}"><defs><linearGradient id="area-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#afd9cc" stop-opacity=".5"/><stop offset="1" stop-color="#afd9cc" stop-opacity="0"/></linearGradient></defs><path d="M30 13H690M30 49H690M30 85H690" stroke="#e9eff0" stroke-dasharray="4 5" fill="none"/><text x="0" y="17">100</text><text x="7" y="53">50</text><text x="14" y="89">0</text><path d="${fill}" fill="url(#area-fill)"/><path d="${path}" stroke="#138674" stroke-width="2.5" fill="none"/>${coords.slice(1).map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="${events[i]?.policy.level>=3?'#bc4543':'#138674'}" stroke="white" stroke-width="2"/><text x="${x}" y="108" text-anchor="middle">第${events[i]?.turn}句</text>`).join('')}${!events.length?'<text x="30" y="107">等待对话</text>':''}</svg>`;
}
function render(){const event=last(),p=engine.policy,copy=seniorCopy();$('.senior-card').className='senior-card '+policyTheme();$('#call-clock').textContent=time(event?.seconds??0);$('#call-status').textContent=event?'正在陪您看这段对话':'准备陪您接电话';$('#senior-message').innerHTML=`<h2>${copy.title}</h2><p>${copy.description}</p>`;$('#acknowledge').hidden=!(p?.level>=1);$('#risk-score').textContent=Math.round((engine.risk.risk??0)*100);$('#policy-tag').textContent=POLICY_LABELS[p?.level??0];$('#policy-tag').className='tag '+policyTheme();$('#decision-action').textContent=p?.title??'继续倾听';$('#decision-reason').textContent=p?.reason??'等待第一句对话';$('#intervention-score').textContent=(p?.score??0).toFixed(2);$('#policy-indicator').style.left=`${Math.min(99,(p?.score??0)*100)}%`;$('#policy-explanation').textContent=p?.held?'高危提醒持续保留，直到本人确认。':p?.reason??'在值得打扰的时刻，再开口。';
 $('#chain').innerHTML=STAGES.map((label,i)=>`<div class="chain-step ${i in engine.graph.visited?'reached':''} ${engine.graph.current===i?'current':''}"><div class="chain-node">${i in engine.graph.visited?'✓':i+1}</div>${label}</div>`).join('');$('#chain-label').textContent=engine.graph.current<0?'尚未形成链路':`有序迁移 ${engine.graph.orderedEdges} 次`;
 $('#signals').innerHTML=event?Object.entries(event.signals).filter(([,v])=>v>0).map(([key])=>`<span class="signal-chip ${ACTIONS.includes(key)?'critical':''}">${SIGNAL_LABELS[key]}</span>`).join('')||'<span class="muted">本句没有新增行为信号</span>':'<span class="muted">行为信号会随每一句对话出现</span>';
 $('#predictions').innerHTML=engine.predictions.length?`${event?.predictionHit?'<p class="badge">上一轮首选预测命中</p>':''}${engine.predictions.map(x=>`<div class="prediction"><span>${x.label}</span><div class="bar"><span style="width:${x.weight}%"></span></div><span>${x.weight}%</span></div>`).join('')}`:'<p class="empty">等待操作线索后，推测下一步动作。</p>';
 $('#utterance-count').textContent=`${engine.history.length} 句`;$('#source-label').textContent=event?.source==='manual'?'手动输入 · 本地处理':'脚本逐句回放 · 时间为脚本标注';$('#transcript').innerHTML=engine.history.length?engine.history.map(e=>`<div class="utterance"><time>${time(e.seconds)}</time><span class="speaker">${e.role==='caller'?'来电方':'老人'}</span><span>${escape(e.text)}</span><span class="utterance-risk">${Math.round(e.risk.risk*100)} 分 · ${POLICY_LABELS[e.policy.level]}</span></div>`).join(''):'<p class="empty">点击「播放演示」或「下一句」，观察系统何时介入。</p>';$('#transcript').scrollTop=$('#transcript').scrollHeight;$('#next').disabled=step>=SCENARIOS[scenario].turns.length;
 renderChart();renderSenior();renderFamily();
}
function acknowledge(){engine.acknowledge();window.speechSynthesis?.cancel();toast('已确认暂不操作。新的危险请求仍会触发提醒。');render();}
function requestFamily(){stop();const event=last();familyEvent={requestedAt:new Date().toISOString(),text:event?.text??null,signals:event?engine.history.flatMap(e=>Object.entries(e.signals).filter(([,value])=>value>0).map(([key])=>SIGNAL_LABELS[key])).filter((x,i,a)=>a.indexOf(x)===i):[],risk:Math.round((engine.risk.risk??0)*100),status:'pending',reportedHarm:engine.history.some(e=>e.reportedHarm)};renderFamily();showView('family');toast('已生成本页家属确认演示，可在右侧模拟回应。');}
function renderSenior(){const copy=seniorCopy();$('#senior').innerHTML=`<div class="standalone-senior"><section class="senior-card ${policyTheme()}"><div class="panel-overline"><span>大字陪护模式</span><span>演示</span></div><div class="guardian-emblem">${$('#emblem').innerHTML}</div><h2>${copy.title}</h2><p>${copy.description}</p><div class="senior-controls"><button class="button family-button" data-action="ask-family">请家人帮我确认</button><button class="button acknowledge" data-action="ack">我先不操作</button><button class="button acknowledge" data-action="next">${step>=SCENARIOS[scenario].turns.length?'再演示一次':'播放下一句对话'}</button></div><p class="phone-foot">当前为演示，未接入真实电话。</p></section></div>`;}
function renderFamily(){if(!familyEvent){$('#family').innerHTML='<section class="card"><span class="badge">家属协同 · 本页模拟</span><h2>此刻，还没有待确认的事。</h2><p class="empty">老人主动选择「请家人帮我确认」后，这里会呈现对话线索和具体危险动作。</p><button class="button primary" data-action="back">回到演示台 →</button></section>';return;}
 const f=familyEvent;$('#family').innerHTML=`<div class="family-layout"><section class="card family-event"><span class="badge">${f.status==='pending'?'待家属确认':'已模拟确认'} · 本页演示</span><h2>家人想请您一起确认。</h2><p>这段对话的动态风险分为 <strong>${f.risk} / 100</strong>。请先帮助老人暂停操作，通过独立渠道核实对方身份。</p>${f.text?`<blockquote>最近一句：<br>“${escape(f.text)}”</blockquote>`:'<p class="empty">尚未记录对话内容。</p>'}<div class="signal-row">${f.signals.map(x=>`<span class="signal-chip">${x}</span>`).join('')||'<span class="muted">暂无已提取线索</span>'}</div><p><strong>操作执行情况：${f.reportedHarm?'用户自述已执行过操作':'未知，系统未接入支付或屏幕操作事件'}</strong></p><p class="fine-print">这里只模拟家属确认流程，没有发送短信、拨打电话或通知真实联系人。</p></section><section class="card"><h2>给家人的下一步</h2><div class="family-events"><div>01 / 请老人先停止共享、提供验证码或转账。</div><div>02 / 通过自己查到的官方联系方式核实。</div><div>03 / 若已发生损失，及时联系相关机构并求助警方。</div></div><div class="family-buttons"><button class="button primary" data-action="family-confirm" ${f.status!=='pending'?'disabled':''}>${f.status==='pending'?'模拟：我已陪同核实':'已模拟陪同核实 ✓'}</button><button class="button secondary" data-action="back">回到对话</button></div>${f.status==='confirmed'?'<p class="family-state" role="status">家属回应已记录在本页。</p>':''}</section></div>`;}
function renderAbout(){ $('#about').innerHTML=`<div class="about-grid"><section class="card wide"><p class="eyebrow">GUARDIAN · HACKATHON MVP</p><h2>把“什么时候开口”变成一个可验证的问题。</h2><p>输入连续对话，提取行为信号，跟踪诱导链路，再决定是否提醒、提醒什么。这里展示的是一个可运行、可复算的规则与状态图原型；没有把启发式分数包装成已训练的 AI 概率。</p><div class="architecture"><span>行为信号提取</span><b>→</b><span>对话演化图</span><b>→</b><span>动态风险更新</span><b>→</b><span>分级介入策略</span></div></section><section class="card"><h2>现在可以现场验证</h2><ul><li>4 个场景逐句回放，也可以输入自己的对话。</li><li>12 类结构化行为信号，有序链路加权。</li><li>危险动作即时抬升风险，高危提醒保留到确认。</li><li>正常客服、否定句和反诈科普对照。</li><li>浏览器语音提醒、老人模式、家属模拟闭环。</li><li>导出本次分析，逐句复核信号和决策。</li></ul></section><section class="card"><h2>下一阶段要补齐</h2><ul><li>在线模型实测、真实 STT、终端通话接入。</li><li>经同意的家属绑定与可靠消息送达。</li><li>真实操作事件，验证提醒是否发生在执行之前。</li><li>独立标注的真实测试集、方言与语音噪声评估。</li></ul><p>当前没有后台监听、支付拦截或真实家属通知。不能据此声称已防止损失。</p></section><section class="card wide"><h2>我们怎样衡量效果</h2><table class="metric-table"><thead><tr><th>指标</th><th>定义</th><th>当前证据</th></tr></thead><tbody><tr><td>BHAR</td><td>在实际危险动作执行前主动提醒的场景 / 有危险动作的场景</td><td>仅在合成脚本时间线上评估</td></tr><tr><td>正常场景误扰率</td><td>触发主动提醒的正常场景 / 正常场景</td><td>公开脚本可复跑</td></tr><tr><td>平均提前时间</td><td>执行时刻 − 首次相关主动提醒时刻</td><td>脚本标注差值，非真实阻止效果</td></tr></tbody></table><p>最终应与关键词、单轮 LLM、无序图谱消融方案进行同一测试集对比。规则参数尚未校准，合成测试通过不等于真实场景有效。</p></section><section class="card wide"><h2>与现有反诈能力形成互补</h2><p>国家反诈中心已有预警、举报与风险核验；国家反诈 AI 的公开介绍也包含多模态研判与防范建议。Guardian 聚焦对话中的动作与介入时机，不宣称官方产品没有行为预防能力，也未进行竞品效果实验。</p><p><a href="https://gat.fujian.gov.cn/ztzl/fjjffpzxrx/yjxx/202309/t20230913_6255881.htm" target="_blank" rel="noopener noreferrer">福建省公安厅：国家反诈中心功能介绍 ↗</a>　<a href="https://touch.shio.gov.cn/jsp/zfxw_detail_en.jsp?id=20260907181214447" target="_blank" rel="noopener noreferrer">上海市政府新闻办：国家反诈 AI 公开介绍 ↗</a></p></section></div>`;}
document.querySelectorAll('.nav').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.view)));
$('#scenario').addEventListener('change',e=>{scenario=e.target.value;reset();});$('#reset').addEventListener('click',reset);$('#next').addEventListener('click',()=>{stop();next();});$('#play').addEventListener('click',togglePlay);$('#family-request').addEventListener('click',requestFamily);$('#acknowledge').addEventListener('click',acknowledge);$('#voice').addEventListener('change',()=>{if(!$('#voice').checked)window.speechSynthesis?.cancel();});
$('#custom-form').addEventListener('submit',async e=>{e.preventDefault();const text=$('#custom-text').value.trim();if(!text){$('#custom-text').focus();return;}stop();const role=$('#speaker').value,epoch=analysisEpoch,submit=$('#custom-form button');submit.disabled=true;let features=null,fallback=false;try{if($('#model-mode')?.checked&&role==='caller'){$('#input-status').textContent='正在请求您配置的模型提取行为信号…';try{const conversation=[...engine.history.slice(-7).map(({role,text})=>({role,text})),{role,text}];const response=await fetch('/api/extract',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({conversation}),signal:AbortSignal.timeout(12000)});if(!response.ok)throw new Error('Model unavailable');features=(await response.json()).signals;}catch{fallback=true;}}if(epoch!==analysisEpoch)return;ingest(text,{role,seconds:(last()?.seconds??0)+1,source:'manual',features});$('#custom-text').value='';$('#input-status').textContent=fallback?'模型暂不可用，本句已明确回退到本地规则。':features?'本句由模型提取信号，本地算法完成决策。':'本句已在本地分析。重置可开启新的对话。';}catch(error){if(epoch===analysisEpoch)$('#input-status').textContent='分析失败：'+error.message;}finally{submit.disabled=false;}});
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='ask-family')requestFamily();if(action==='ack')acknowledge();if(action==='next'){stop();if(step>=SCENARIOS[scenario].turns.length)reset();next();}if(action==='back')showView('dashboard');if(action==='family-confirm'&&familyEvent){familyEvent.status='confirmed';renderFamily();toast('已模拟家属回应。');}});
$('#export').addEventListener('click',()=>{const report={...engine.export(),scenario,familyEvent};const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='guardian-session.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('分析记录已导出。');});
window.addEventListener('pagehide',()=>{stop();window.speechSynthesis?.cancel();});
render();renderAbout();$('#play').textContent='▶ 播放演示';
// Local development and Hugging Face expose the configured server-side model provider.
if(location.hostname==='127.0.0.1'||location.hostname==='localhost'||location.hostname.endsWith('.hf.space'))fetch('/api/capabilities').then(r=>r.ok?r.json():null).then(cap=>{if(!cap?.llmConfigured)return;const label=document.createElement('label');label.className='model-toggle';label.innerHTML='<input type="checkbox" id="model-mode"> 手动输入使用在线模型提取';$('#custom-form').before(label);$('#model-mode').addEventListener('change',()=>{analysisEpoch++;$('#input-status').textContent=$('#model-mode').checked?'输入会将本次最近最多8句发送到您配置的模型服务；演示脚本仍使用本地规则。':'已切回本地规则，后续输入不会请求模型。';});}).catch(()=>{});
// Optional browser agent interface; reuses the exact visible state transitions.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'guardian_read_session',description:'Read this local Guardian demonstration and its heuristic analysis.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>engine.export()});
 register({name:'guardian_analyze_utterance',description:'Analyze one caller or senior utterance locally and update the visible Guardian demonstration; never sends notifications.',inputSchema:{type:'object',properties:{text:{type:'string',minLength:1,maxLength:500},role:{type:'string',enum:['caller','user']}},required:['text'],additionalProperties:false},execute:input=>{if(!input||typeof input.text!=='string'||(input.role&&!['caller','user'].includes(input.role)))throw new TypeError('Invalid utterance');stop();return ingest(input.text,{role:input.role??'caller',seconds:(last()?.seconds??0)+1,source:'manual'});}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
